/** Sprite symbol ids for Assistant handoff targets, keyed like `assistant-handoff`. */
export const ASSISTANT_ICON_IDS = {
  claude: "icon-claude",
  chatgpt: "icon-chatgpt",
  t3: "icon-t3",
  cursor: "icon-cursor",
} as const;

/**
 * One icon taken out of the sprite above. `id` is a symbol id without the `#`,
 * so a caller names the icon instead of hand-writing the `<use>` markup that
 * makes it size and colour like the text around it.
 */
export const SpriteIcon = ({
  id,
  className,
}: {
  id: string;
  className?: string;
}) => (
  <svg aria-hidden focusable="false" className={className}>
    <use href={`#${id}`} />
  </svg>
);
